// shape/strides describe a view of a buffer; k is a logical position in row-major order (0 .. numel-1).
// Return the buffer index that position reads.
int view_at(int ndim, const int *shape, const int *strides, int offset, int k) {
  return offset + k;   // only right for a contiguous row-major view
}

